// B-7: body must be exactly {t} and t must be one of the fixed safety template ids. No free text, ever.
const SAFETY = ['storm_warning', 'flood_watch', 'heat_alert', 'family_sos'];
const body = $json.body;
const auth = String($json.headers.authorization || '');
const ok = body && typeof body === 'object' && Object.keys(body).length === 1 && typeof body.t === 'string' && SAFETY.includes(body.t) && /^Bearer [A-Za-z0-9._-]+$/.test(auth);
return { json: { valid: !!ok, t: ok ? body.t : null, token: ok ? auth.slice(7) : null } };

// Needs NODE_FUNCTION_ALLOW_EXTERNAL=web-push on the n8n host, and VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY / VAPID_SUBJECT env vars.
const webpush = require('web-push');
webpush.setVapidDetails($env.VAPID_SUBJECT, $env.VAPID_PUBLIC_KEY, $env.VAPID_PRIVATE_KEY);
const t = $('Validate body').first().json.t;
const payload = JSON.stringify({ t }); // B-7: the payload is the template id and nothing else
let sent = 0, gone = 0;
for (const s of $input.all()) {
  const { endpoint, p256dh, auth } = s.json;
  try { await webpush.sendNotification({ endpoint, keys: { p256dh, auth } }, payload, { TTL: 3600, urgency: 'high' }); sent++; }
  catch (e) { if (e.statusCode === 404 || e.statusCode === 410) gone++; }
}
return [{ json: { sent, gone } }];
